// controlSize: the five sizes a control takes, and the type-role size each one sets its text in.
// A control's height, padding, icon and corner have a rung per size; the type roles keep three
// (ADR-0054 Amendment 1), so `x-small` sets its text in the `small` role and `x-large` in `large`.
export type ControlSize = "x-small" | "small" | "medium" | "large" | "x-large";

export type RoleSize = "small" | "medium" | "large";

export const roleSize = (size: ControlSize): RoleSize =>
  size === "x-small" ? "small" : size === "x-large" ? "large" : size;
